page Sim "/" {
  const W = 400
  const H = 300
  const R = 10

  state count = 5
  state frames = 0
  state paused = false

  ref cv
  ref balls
  ref raf
  ref pausedRef
  ref framesRef

  fn rnd(a, b) {
    return a + Math.random() * (b - a)
  }

  fn make() {
    return {
      x: rnd(R, W - R),
      y: rnd(R, H - R),
      vx: rnd(-3, 3),
      vy: rnd(-3, 3)
    }
  }

  fn reset() {
    let arr = []
    for (let i = 0; i < 5; i++) {
      arr.push(make())
    }
    balls = arr
    framesRef = 0
    frames = 0
    count = 5
  }

  fn add() {
    balls.push(make())
    count = balls.length
  }

  fn toggle() {
    paused = !paused
    pausedRef = paused
  }

  fn step() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if b.x < R {
        b.x = R
        b.vx = Math.abs(b.vx)
      }
      if b.x > W - R {
        b.x = W - R
        b.vx = -Math.abs(b.vx)
      }
      if b.y < R {
        b.y = R
        b.vy = Math.abs(b.vy)
      }
      if b.y > H - R {
        b.y = H - R
        b.vy = -Math.abs(b.vy)
      }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let b = balls[j]
        let dx = b.x - a.x
        let dy = b.y - a.y
        let d = Math.sqrt(dx * dx + dy * dy)
        if d < 2 * R {
          if d == 0 {
            dx = 1
            dy = 0
            d = 1
          }
          let nx = dx / d
          let ny = dy / d
          let overlap = 2 * R - d
          a.x -= nx * overlap / 2
          a.y -= ny * overlap / 2
          b.x += nx * overlap / 2
          b.y += ny * overlap / 2
          let tx = a.vx
          let ty = a.vy
          a.vx = b.vx
          a.vy = b.vy
          b.vx = tx
          b.vy = ty
        }
      }
    }
  }

  fn draw() {
    let ctx = cv.getContext("2d")
    ctx.clearRect(0, 0, W, H)
    ctx.fillStyle = "#3b82f6"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    if !pausedRef {
      step()
      draw()
      framesRef = framesRef + 1
      frames = framesRef
    }
    raf = requestAnimationFrame(loop)
  }

  mount {
    pausedRef = false
    reset()
    loop()
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    canvas ref=cv id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" -> add()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

page Sim "/" {
  state balls = []
  state paused = false
  state frames = 0
  ref cv
  ref raf
  ref world

  fn rnd(a, b) {
    return a + Math.random() * (b - a)
  }

  fn makeBall() {
    return { x: rnd(10, 390), y: rnd(10, 290), vx: rnd(-3, 3), vy: rnd(-3, 3), r: 10 }
  }

  fn reset() {
    world = []
    for (let i = 0; i < 5; i++) {
      world.push(makeBall())
    }
    balls = world.slice()
    frames = 0
  }

  fn add() {
    world.push(makeBall())
    balls = world.slice()
  }

  fn togglePause() {
    paused = !paused
    if !paused {
      loop()
    }
  }

  fn step() {
    for (let i = 0; i < world.length; i++) {
      let b = world[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx) }
      if (b.x > 400 - b.r) { b.x = 400 - b.r; b.vx = -Math.abs(b.vx) }
      if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy) }
      if (b.y > 300 - b.r) { b.y = 300 - b.r; b.vy = -Math.abs(b.vy) }
    }
    for (let i = 0; i < world.length; i++) {
      for (let j = i + 1; j < world.length; j++) {
        let a = world[i]
        let c = world[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let d = Math.sqrt(dx * dx + dy * dy)
        let min = a.r + c.r
        if (d < min) {
          let nx = d == 0 ? 1 : dx / d
          let ny = d == 0 ? 0 : dy / d
          let push = (min - d) / 2
          a.x -= nx * push
          a.y -= ny * push
          c.x += nx * push
          c.y += ny * push
          a.x = Math.min(400 - a.r, Math.max(a.r, a.x))
          a.y = Math.min(300 - a.r, Math.max(a.r, a.y))
          c.x = Math.min(400 - c.r, Math.max(c.r, c.x))
          c.y = Math.min(300 - c.r, Math.max(c.r, c.y))
          let tx = a.vx
          let ty = a.vy
          a.vx = c.vx
          a.vy = c.vy
          c.vx = tx
          c.vy = ty
        }
      }
    }
  }

  fn draw() {
    let ctx = cv.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#e11d48"
    for (let i = 0; i < world.length; i++) {
      let b = world[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    if paused { return }
    step()
    draw()
    frames++
    raf = requestAnimationFrame(loop)
  }

  mount {
    reset()
    loop()
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    canvas id="sim" ref=cv width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" -> add()
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${balls.length}`
    text `Cuadros: ${frames}`
  }
}

// ---------- Datos de ejemplo ----------
const TRAVELERS = [
  { id: 1, name: "Ana Rojas", country: "Perú", city: "Lima", arrival: "2026-03-12", budget: 1200 },
  { id: 2, name: "Bruno Díaz", country: "México", city: "Oaxaca", arrival: "2026-01-05", budget: 850 },
  { id: 3, name: "Carla Gómez", country: "Perú", city: "Cusco", arrival: "2026-02-20", budget: 2300 },
  { id: 4, name: "Diego Silva", country: "Chile", city: "Valparaíso", arrival: "2026-04-02", budget: 640 },
  { id: 5, name: "Elena Ruiz", country: "México", city: "Mérida", arrival: "2026-03-01", budget: 1500 },
  { id: 6, name: "Facundo Paz", country: "Argentina", city: "Salta", arrival: "2026-02-11", budget: 990 },
  { id: 7, name: "Gabriela Luna", country: "Chile", city: "Santiago", arrival: "2026-01-28", budget: 1750 },
  { id: 8, name: "Hugo Vera", country: "Argentina", city: "Mendoza", arrival: "2026-03-30", budget: 1100 }
]

const COUNTRIES = ["Todos", "Argentina", "Chile", "México", "Perú"]

// ---------- Utilidades de formato ----------
fn formatDate(iso) {
  const [y, m, d] = iso.split("-")
  return `${d}/${m}/${y}`
}

fn formatUSD(n) {
  return "US$ " + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ".")
}

fn initials(name) {
  return name.split(" ").filter(p => p.length > 0).slice(0, 2).map(p => p[0].toUpperCase()).join("")
}

fn avatarColor(name) {
  let h = 0
  for (let i = 0; i < name.length; i++) {
    h = (h * 31 + name.charCodeAt(i)) % 360
  }
  return `hsl(${h}, 55%, 45%)`
}

fn place(t) {
  return `${t.city}, ${t.country}`
}

// ---------- Componentes ----------
component Avatar(name: String) {
  row class="avatar" align=center justify=center style=(`background:${avatarColor(name)}`) {
    text initials(name) bold
  }
  style {
    .avatar { width: 44px; height: 44px; border-radius: 50%; color: #fff; flex-shrink: 0 }
  }
}

component TravelerRow(t: Any) {
  card pad=3 {
    row gap=3 align=center {
      Avatar name=t.name
      column gap=1 {
        link t.name to=(`/viajero/${t.id}`) bold
        text place(t) muted
        text `Llega el ${formatDate(t.arrival)}` small
        text formatUSD(t.budget) small
      }
    }
  }
}

// ---------- Páginas ----------
page Home "/" {
  meta title="Viajeros"
  state country = "Todos"
  computed shown = TRAVELERS
    .filter(t => country == "Todos" || t.country == country)
    .sort((a, b) => a.arrival < b.arrival ? -1 : a.arrival > b.arrival ? 1 : 0)

  column gap=4 pad=4 {
    title "Viajeros" tag=h1
    text `${shown.length} viajeros`
    select country options=COUNTRIES label="País"
    column gap=3 {
      for t in shown key t.id {
        TravelerRow t=t
      }
    }
  }
}

page Traveler "/viajero/:id" {
  computed t = TRAVELERS.find(x => String(x.id) == params.id)

  column gap=3 pad=4 {
    if t {
      title t.name tag=h1
      text place(t)
      text `Llega el ${formatDate(t.arrival)}`
      text `Presupuesto: ${formatUSD(t.budget)}`
    } else {
      title "Viajero no encontrado"
    }
    link "Volver" to="/"
  }
}

